+export function totalCents(lines, discountPercent) {
+  // Sum integer line cents first, then apply the discount and round the total once.
+  // Rounding per line compounds: e.g. two 1-cent lines at 50% each round up to 1,
+  // yielding 2 instead of round(2 * 0.5) = 1.
+  const subtotal = lines.reduce((sum, line) => sum + line.cents * line.quantity, 0);
+  return Math.round(subtotal * (1 - discountPercent / 100));
+}

